<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Taxonomy;
use App\Domain\Taxonomy\Repository\TaxonomySubjectMergeApplierInterface;use App\Infrastructure\Persistence\Doctrine\Catalog\Entity\SubjectTaxonomyAssignmentRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionTaxonomySubjectRecord;use App\Infrastructure\Persistence\Doctrine\Taxonomy\Entity\TaxonomySubjectAliasRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineTaxonomySubjectMergeApplier implements TaxonomySubjectMergeApplierInterface { public function __construct(private readonly EntityManagerInterface $entityManager){} public function reassignCanonicalReferences(string $sourceSubjectId,string $targetSubjectId):void{$this->removeQuestionDuplicates($sourceSubjectId,$targetSubjectId);$this->removeSubjectDuplicates($sourceSubjectId,$targetSubjectId);$this->reassign(QuestionTaxonomySubjectRecord::class,'questionId','taxonomySubjectId',$sourceSubjectId,$targetSubjectId);$this->reassign(SubjectTaxonomyAssignmentRecord::class,'subjectId','taxonomySubjectId',$sourceSubjectId,$targetSubjectId);$this->entityManager->createQueryBuilder()->update(TaxonomySubjectAliasRecord::class,'alias')->set('alias.subjectId',':target')->where('alias.subjectId=:source')->setParameter('source',$sourceSubjectId)->setParameter('target',$targetSubjectId)->getQuery()->execute();} private function removeQuestionDuplicates(string $source,string $target):void{$ids=$this->duplicateIds(QuestionTaxonomySubjectRecord::class,'questionId','taxonomySubjectId',$source,$target);foreach($ids as $id)$this->entityManager->createQueryBuilder()->delete(QuestionTaxonomySubjectRecord::class,'assignment')->where('assignment.questionId=:id')->andWhere('assignment.taxonomySubjectId=:source')->setParameter('id',$id)->setParameter('source',$source)->getQuery()->execute();} private function removeSubjectDuplicates(string $source,string $target):void{$ids=$this->duplicateIds(SubjectTaxonomyAssignmentRecord::class,'subjectId','taxonomySubjectId',$source,$target);foreach($ids as $id)$this->entityManager->createQueryBuilder()->delete(SubjectTaxonomyAssignmentRecord::class,'assignment')->where('assignment.subjectId=:id')->andWhere('assignment.taxonomySubjectId=:source')->setParameter('id',$id)->setParameter('source',$source)->getQuery()->execute();} private function duplicateIds(string $class,string $owner,string $taxonomy,string $source,string $target):array{$targetIds=$this->entityManager->createQueryBuilder()->select('target.'.$owner)->from($class,'target')->where('target.'.$taxonomy.'=:target')->setParameter('target',$target)->getQuery()->getSingleColumnResult();if($targetIds===[])return[];return $this->entityManager->createQueryBuilder()->select('source.'.$owner)->from($class,'source')->where('source.'.$taxonomy.'=:source')->andWhere('source.'.$owner.' IN (:ids)')->setParameter('source',$source)->setParameter('ids',$targetIds)->getQuery()->getSingleColumnResult();} private function reassign(string $class,string $owner,string $taxonomy,string $source,string $target):void{$this->entityManager->createQueryBuilder()->update($class,'assignment')->set('assignment.'.$taxonomy,':target')->where('assignment.'.$taxonomy.'=:source')->setParameter('source',$source)->setParameter('target',$target)->getQuery()->execute();} }
